   double dev;
   double d;
   double ci;
   double wt1;
   double prevAp;
   double prevEsa;
   double num;
   double scaledDev;
   double sumEsa;
   double sumD;
   double sumCi;
   double sumSignal;
   int lookbackTotal;
   int lookbackChannel;
   int lookbackAverage;
   int today;
   int outIdx;
   int nAp;
   int nDev;
