/**** Global functions definitions.   ****/
/* Calls of TA_Initialize and of TA_Shutdown since the process started. Outside
 * TA_Globals, which both of them clear.
 */
static int nbInitialize = 0;
static int nbShutdown = 0;

#if TA_VMATH_KERNEL
/* Every routine a TA_VMATH_MAP loop binds, and what each was bound to. The first
 * attempt decides for good, so TA_Initialize, the loops and TA_GetRuntimeInfo share
 * one answer.
 */
static const char *const vmathRoutine[] =
{
   "vvacos", "vvasin", "vvatan", "vvcos", "vvcosh", "vvexp",
   "vvlog", "vvlog10", "vvsin", "vvsinh", "vvtan", "vvtanh"
};
#define NB_VMATH_ROUTINE (sizeof(vmathRoutine)/sizeof(vmathRoutine[0]))
static TA_VMathRoutine vmathBound[NB_VMATH_ROUTINE];

/* What TA_VMathBind answers when vForce cannot be reached. A call site keeps it
 * like any routine, so the lookup is not repeated. Never called.
 */
void TA_VMathUnbound( double *out, const double *in, const int *count )
{
   (void)out;
   (void)in;
   (void)count;
}

extern void *dlopen( const char *path, int mode );
extern void *dlsym( void *handle, const char *symbol );

/* The first image holds vForce alone and loads in a small fraction of the time the
 * whole framework takes; the framework is the documented path, kept behind it.
 * Each image is tried once: a slot that holds the array's own address did not open.
 */
static TA_VMathRoutine vmathOpen( const char *symbol )
{
   static const char *const image[] =
   {
      "/System/Library/Frameworks/Accelerate.framework/Versions/A/Frameworks/vecLib.framework/Versions/A/libvMisc.dylib",
      "/System/Library/Frameworks/Accelerate.framework/Versions/A/Accelerate"
   };
   static void *opened[sizeof(image)/sizeof(image[0])];
   unsigned int i;

   for( i = 0; i < sizeof(image)/sizeof(image[0]); i++ )
   {
      void *handle = __atomic_load_n( &opened[i], __ATOMIC_RELAXED );
      if( !handle )
      {
         handle = dlopen( image[i], 0x5 /* RTLD_LAZY | RTLD_LOCAL */ );
         if( !handle ) handle = (void *)opened;
         __atomic_store_n( &opened[i], handle, __ATOMIC_RELAXED );
      }
      if( handle != (void *)opened )
      {
         void *routine = dlsym( handle, symbol );
         if( routine ) return __extension__ (TA_VMathRoutine)routine;
      }
   }
   return TA_VMathUnbound;
}

TA_VMathRoutine TA_VMathBind( const char *symbol )
{
   unsigned int i;

   for( i = 0; i < NB_VMATH_ROUTINE; i++ )
   {
      if( strcmp( vmathRoutine[i], symbol ) == 0 )
      {
         TA_VMathRoutine routine = __atomic_load_n( &vmathBound[i], __ATOMIC_RELAXED );
         if( !routine )
         {
            TA_VMathRoutine found = vmathOpen( symbol );
            if( __atomic_compare_exchange_n( &vmathBound[i], &routine, found, 0,
                                             __ATOMIC_RELAXED, __ATOMIC_RELAXED ) )
               routine = found;
         }
         return routine;
      }
   }
   return TA_VMathUnbound;
}
#endif

TA_RetCode TA_GetRuntimeInfo( const char *key, int *value )
{
   if( !key || !value ) return TA_BAD_PARAM;
   if( strcmp( key, "count.initialize" ) == 0 )
   {
      *value = nbInitialize;
      return TA_SUCCESS;
   }
   if( strcmp( key, "count.shutdown" ) == 0 )
   {
      *value = nbShutdown;
      return TA_SUCCESS;
   }
   if( strcmp( key, "vmath.transcendental" ) != 0 ) return TA_BAD_PARAM;
#if TA_VMATH_KERNEL
   {
      unsigned int i;

      for( i = 0; i < NB_VMATH_ROUTINE; i++ )
      {
         TA_VMathRoutine routine = __atomic_load_n( &vmathBound[i], __ATOMIC_RELAXED );
         if( !routine || routine == TA_VMathUnbound )
         {
            *value = 0;
            return TA_SUCCESS;
         }
      }
   }
   *value = 1;
#else
   *value = 0;
#endif
   return TA_SUCCESS;
}

TA_RetCode TA_Initialize( void )
{
   TA_RetCode retCode;

   nbInitialize++;

   /* Initialize the "global variable" used to manage the global
    * variables of all other modules...
    */
   memset( TA_Globals, 0, sizeof( TA_LibcPriv ) );

   /* Set the default value to global variables. The return is checked: it is
    * how the defaults table's own completeness guard reaches a caller, and a
    * library initialized with unset candle settings silently changes every
    * CDL* result rather than failing. */
   retCode = TA_RestoreCandleDefaultSettings( TA_AllCandleSettings );
   if( retCode != TA_SUCCESS )
      return retCode;

#if TA_VMATH_KERNEL
   {
      unsigned int i;

      for( i = 0; i < NB_VMATH_ROUTINE; i++ )
         (void)TA_VMathBind( vmathRoutine[i] );
   }
#endif

   return TA_SUCCESS;
}

TA_RetCode TA_Shutdown( void )
{
   nbShutdown++;

   /* Idempotent, like TA_Initialize: every call leaves the defaults in force. */
   memset( TA_Globals, 0, sizeof( TA_LibcPriv ) );

   return TA_RestoreCandleDefaultSettings( TA_AllCandleSettings );
}

/* A setting at 12 or above means candleSettings[] reaches past index 11,
 * which TA_AllCandleSettings keeps: every loop over the table, and every
 * table of per-setting rows, must then skip index 11 before this can go. */
typedef char TA_CandleSettingsStopBeforeTheSelector
   [ (TA_NB_CANDLE_SETTING <= (int)TA_AllCandleSettings) ? 1 : -1 ];

TA_RetCode TA_SetCandleSettings( TA_CandleSettingType settingType,
                                 TA_RangeType rangeType,
                                 int avgPeriod,
                                 double factor )
{
    /*printf("setcdlset:%d  ",settingType);*/

    /* Unsigned compares, as in TA_SetUnstablePeriod (#144), so a negative value
     * cannot index behind candleSettings[] where the compiler gives the enum a
     * signed underlying type. TA_AllCandleSettings selects "all" only for
     * TA_RestoreCandleDefaultSettings, so it is not a target here; an
     * out-of-domain rangeType would reach TA_CANDLERANGE's fall-through arm
     * and measure every range as zero. */
    if( settingType == TA_AllCandleSettings
        || (unsigned int)settingType >= (unsigned int)TA_NB_CANDLE_SETTING )
        return TA_BAD_PARAM;
    if( (unsigned int)rangeType > (unsigned int)TA_RangeType_Shadows )
        return TA_BAD_PARAM;

    /* avgPeriod enters the lookback of every function that reads this
     * setting, so it is bounded like one (#185). A negative one starts the main
     * loop that many bars late while *outBegIdx still reports startIdx -- every
     * value shifted under a correct-looking index, and a lookback reporting
     * negative while the call returns TA_SUCCESS. TA_INDEX_MAX is the ceiling
     * TA_SetUnstablePeriod already uses for the same reason: above it the
     * `max(...)+N` lookbacks overflow signed-negative into that same state, and
     * a warm-up longer than the largest addressable series could never produce
     * output. */
    if( avgPeriod < 0 || avgPeriod > TA_INDEX_MAX )
        return TA_BAD_PARAM;

    /* factor scales a threshold: finite and not negative. NaN silences every
     * comparison it feeds, an infinity times a zero average is NaN, and a
     * negative threshold is below every range. Written so that NaN fails it. */
    if( !(factor >= 0.0 && factor <= DBL_MAX) )
        return TA_BAD_PARAM;

    TA_Globals->candleSettings[settingType].settingType = settingType;
    TA_Globals->candleSettings[settingType].rangeType = rangeType;
    TA_Globals->candleSettings[settingType].avgPeriod = avgPeriod;
    TA_Globals->candleSettings[settingType].factor = factor;
    /*printf("cdlset: %d %d %d %f\n",TA_Globals->candleSettings[settingType].settingType,TA_Globals->candleSettings[settingType].rangeType,
        TA_Globals->candleSettings[settingType].avgPeriod,TA_Globals->candleSettings[settingType].factor);*/
    return TA_SUCCESS;
}

TA_RetCode TA_RestoreCandleDefaultSettings( TA_CandleSettingType settingType )
{
    static const TA_CandleSetting TA_CandleDefaultSettings[] = { TA_CANDLE_DEFAULT_SETTINGS };

    int i;

    /* One row per setting, or the indexing below reads past the end.
     * Constant-folded away when it holds; a setting added without a row here
     * becomes a clean error instead of an over-read. */
    if( sizeof(TA_CandleDefaultSettings)/sizeof(TA_CandleDefaultSettings[0])
        != (size_t)TA_NB_CANDLE_SETTING )
        return TA_INTERNAL_ERROR(482);

    if( settingType == TA_AllCandleSettings )
        for( i = 0; i < TA_NB_CANDLE_SETTING; ++i )
            TA_Globals->candleSettings[i] = TA_CandleDefaultSettings[i];
    else if( (unsigned int)settingType >= (unsigned int)TA_NB_CANDLE_SETTING )
        return TA_BAD_PARAM;
    else
        TA_Globals->candleSettings[settingType] = TA_CandleDefaultSettings[settingType];
    return TA_SUCCESS;
}

